import roman.core as r
# Test basic cases
assert r.to_roman(1) == 'I'
assert r.to_roman(4) == 'IV'
assert r.to_roman(9) == 'IX'
assert r.to_roman(40) == 'XL'
assert r.to_roman(90) == 'XC'
assert r.to_roman(400) == 'CD'
assert r.to_roman(900) == 'CM'
assert r.to_roman(2024) == 'MMXXIV'
assert r.to_roman(3999) == 'MMMCMXCIX'
assert r.to_roman(1994) == 'MCMXCIV'
# Test type errors
try:
    r.to_roman('5')
except TypeError:
    pass
else:
    raise AssertionError('Expected TypeError for string')
try:
    r.to_roman(5.0)
except TypeError:
    pass
else:
    raise AssertionError('Expected TypeError for float')
try:
    r.to_roman(None)
except TypeError:
    pass
else:
    raise AssertionError('Expected TypeError for None')
try:
    r.to_roman([1])
except TypeError:
    pass
else:
    raise AssertionError('Expected TypeError for list')
# Test value errors
try:
    r.to_roman(0)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError for 0')
try:
    r.to_roman(-1)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError for -1')
try:
    r.to_roman(4000)
except ValueError:
    pass
else:
    raise AssertionError('Expected ValueError for 4000')
print('All tests passed')
